package com.example.demo;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
@RestController
class PageController {
  @GetMapping("/page")
  int page(@RequestParam(defaultValue = "20") int taille) {
    if (taille < 1 || taille > 100)
      throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "taille entre 1 et 100");
    return taille;
  }
}

package com.example.demo;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class PrixServiceTest {
  @Test void calculeUnTotal() {
    assertEquals(15, new PrixService().total(5, 3));
  }
  @Test void refuseUneQuantiteNegative() {
    assertThrows(IllegalArgumentException.class,
      () -> new PrixService().total(5, -1));
  }
}

package com.example.demo;
class PrixService {
  int total(int prix, int quantite) {
    if (prix < 0 || quantite < 0) throw new IllegalArgumentException();
    return Math.multiplyExact(prix, quantite);
  }
}
